      const width = tabSize - (column % tabSize);
      out += ' '.repeat(width);
      column += width;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      column = 0;
    } else {
      out += ch;
      column += 1;
    }
  }
  return out;
