export function pyStrip(text) {
  return pyRStrip(pyLStrip(text));
}

export function pyLStrip(text, chars) {
  let i = 0;
  while (i < text.length && (chars ? chars.includes(text[i]) : isSpace(text[i]))) i += 1;
  return text.slice(i);
}

export function pyRStrip(text, chars) {
  let i = text.length;
  while (i > 0 && (chars ? chars.includes(text[i - 1]) : isSpace(text[i - 1]))) i -= 1;
  return text.slice(0, i);
}

/** True when the string contains nothing but whitespace. */
export function isBlank(text) {
  for (const ch of text) {
    if (!isSpace(ch)) return false;
  }
  return true;
}

/** Python `str.expandtabs(n)`. */
export function expandTabs(text, tabSize) {
  let out = '';
  let column = 0;
  for (const ch of text) {
    if (ch === '\t') {
      const width = tabSize - (column % tabSize);
      out += ' '.repeat(width);
      column += width;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      column = 0;
    } else {
