  return out;
}

/** True when `text` has `needle` starting at `index`. */
export function startsWithAt(text, needle, index) {
  return text.startsWith(needle, index);
}

/** Count how many consecutive `ch` occur starting at `index`. */
export function runLength(text, index, ch) {
  let n = 0;
  while (index + n < text.length && text[index + n] === ch) n += 1;
  return n;
}

