/**
 * Shared constants, the atomic-string marker, the ordered registry and the
 * raw-HTML stash.  Mirrors the helper layer of the reference implementation.
 */

export const STX = '';
export const ETX = '';

export const INLINE_PLACEHOLDER_PREFIX = `${STX}klzzwxh:`;
export const AMP_SUBSTITUTE = `${STX}amp${ETX}`;
export const HTML_PLACEHOLDER_PREFIX = `${STX}wzxhzdk:`;

export const TAB_LENGTH = 4;

export function inlinePlaceholder(id) {
  return `${INLINE_PLACEHOLDER_PREFIX}${id}${ETX}`;
}

export function htmlPlaceholder(id) {
  return `${HTML_PLACEHOLDER_PREFIX}${id}${ETX}`;
}

/**
 * Text that must never be re-scanned by the inline processors (code spans,
 * verbatim code blocks, autolink labels...).
 */
export class AtomicString {
  constructor(value) {
    this.value = value;
  }

  toString() {
    return this.value;
  }
}

export function isAtomic(value) {
  return value instanceof AtomicString;
}

/** Unwrap an `AtomicString` (or pass a plain value through untouched). */
export function S(value) {
  return value instanceof AtomicString ? value.value : value;
}

/** Elements that may not be wrapped in a `<p>` / are left verbatim. */
export const BLOCK_LEVEL_ELEMENTS = new Set([
  'address', 'article', 'aside', 'blockquote', 'body', 'canvas', 'center',
  'colgroup', 'dd', 'details', 'div', 'dl', 'dt', 'fieldset', 'figcaption',
  'figure', 'footer', 'form', 'group', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
  'header', 'hgroup', 'hr', 'html', 'iframe', 'legend', 'li', 'main', 'map',
  'math', 'menu', 'nav', 'noscript', 'object', 'ol', 'option', 'output', 'p',
  'pre', 'progress', 'script', 'section', 'style', 'summary', 'table', 'tbody',
  'td', 'textarea', 'tfoot', 'th', 'thead', 'tr', 'ul', 'video',
]);

export const ESCAPED_CHARS = [
  '\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '>', '#', '+', '-', '.', '!',
];

/** HTML-escape a chunk of literal code. */
export function codeEscape(text) {
  let out = text;
  if (out.includes('&')) out = out.split('&').join('&amp;');
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  return out;
}

/** An insertion-ordered, priority-sorted collection of processors. */
export class Registry {
  constructor() {
    this._items = [];
    this._byName = new Map();
  }

  register(item, name, priority) {
    this._items.push({ item, name, priority });
    this._items.sort((a, b) => b.priority - a.priority);
    this._byName.set(name, item);
  }

  get(name) {
    return this._byName.get(name);
  }

  [Symbol.iterator]() {
    return this._items.map((entry) => entry.item)[Symbol.iterator]();
  }
}

/** Holds raw HTML removed from the source so markdown never touches it. */
export class HtmlStash {
  constructor() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
  }

  store(html) {
    this.rawHtmlBlocks.push(html);
    const placeholder = htmlPlaceholder(this.htmlCounter);
    this.htmlCounter += 1;
    return placeholder;
  }

  getPlaceholder(key) {
    return htmlPlaceholder(key);
  }
}

