/**
 * A minimal ElementTree work-alike: elements carry a tag, ordered attributes,
 * `text` (content before the first child) and `tail` (content after the
 * element itself).
 */

import { S } from './util.mjs';

export class Element {
  constructor(tag) {
    this.tag = tag;
    this.attrib = new Map();
    this.text = null;
    this.tail = null;
    this.children = [];
  }

  get length() {
    return this.children.length;
  }

  set(key, value) {
    this.attrib.set(key, value);
  }

  get(key) {
    return this.attrib.get(key);
  }

  items() {
    return [...this.attrib.entries()];
  }

  append(child) {
    this.children.push(child);
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
  }

  indexOf(child) {
    return this.children.indexOf(child);
  }

  child(index) {
    if (index < 0) return this.children[this.children.length + index];
    return this.children[index];
  }

  get last() {
    return this.children.length ? this.children[this.children.length - 1] : undefined;
  }

  /** Depth-first walk over this element and every descendant. */
  *iter(tag) {
    if (tag === undefined || tag === this.tag) yield this;
    for (const child of this.children) yield* child.iter(tag);
  }

  /** Concatenation of every text node inside this element. */
  itertext() {
    let out = '';
    if (this.text) out += S(this.text);
    for (const child of this.children) {
      out += child.itertext();
      if (child.tail) out += S(child.tail);
    }
    return out;
  }
}

export function SubElement(parent, tag) {
  const el = new Element(tag);
  parent.append(el);
  return el;
}

