import { isAsciiLetter, isAsciiAlnum, isDigit, isHexDigit } from './chars.mjs';

const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

/**
 * Equivalent of `&(?!(?:\#[0-9]+|\#x[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);)`:
 * report whether the `&` at `index` opens a well formed reference.
 */
function startsCharacterReference(text, index) {
  let i = index + 1;
  if (i >= text.length) return false;
  if (text[i] === '#') {
    i += 1;
    if (text[i] === 'x' || text[i] === 'X') {
      // Only lowercase `x` is accepted by the reference implementation.
      if (text[i] !== 'x') return false;
      i += 1;
      let seen = 0;
      while (i < text.length && isHexDigit(text[i])) { i += 1; seen += 1; }
      return seen > 0 && text[i] === ';';
    }
    let seen = 0;
    while (i < text.length && isDigit(text[i])) { i += 1; seen += 1; }
    return seen > 0 && text[i] === ';';
  }
  if (!isAsciiLetter(text[i])) return false;
  i += 1;
  while (i < text.length && isAsciiAlnum(text[i])) i += 1;
  return text[i] === ';';
}

function escapeAmp(text) {
  if (!text.includes('&')) return text;
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '&' && !startsCharacterReference(text, i)) out += '&amp;';
    else out += text[i];
  }
  return out;
}

function escapeCdata(text) {
  let out = escapeAmp(text);
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  return out;
}

function escapeAttrib(text) {
  let out = escapeAmp(text);
  if (out.includes('<')) out = out.split('<').join('&lt;');
  if (out.includes('>')) out = out.split('>').join('&gt;');
  if (out.includes('"')) out = out.split('"').join('&quot;');
  return out;
}

function serializeElement(parts, el) {
  const tag = el.tag;
  const text = S(el.text);
  parts.push(`<${tag}`);
  const items = el.items();
  if (items.length) {
    items.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
    for (const [key, value] of items) {
      if (value === null || value === undefined) parts.push(` ${key}`);
      else parts.push(` ${key}="${escapeAttrib(String(value))}"`);
    }
  }
  if (HTML_EMPTY.has(tag.toLowerCase())) {
    parts.push(' />');
  } else {
    parts.push('>');
