/** Same shape as `searchBlockQuote` but anchored to a single line. */
export function matchBlockQuoteLine(line) {
  const indent = leadingSpaces(line, 0, 3);
  if (line[indent] !== '>') return null;
  let contentStart = indent + 1;
  if (line[contentStart] === ' ') contentStart += 1;
  return line.slice(contentStart);
}

/**
 * `^[ ]{0,3}((\d+\.)|[*+-])[ ]+(.*)` - a list item on a single line.
 * `kind` is `'ol'` or `'ul'`; `marker` is the raw bullet/number text.
