    kind = 'ul';
    markerEnd = i + 1;
  } else {
    return null;
  }
  let k = markerEnd;
  while (k < line.length && line[k] === ' ') k += 1;
  if (k === markerEnd) return null;
  return { kind, marker: line.slice(indent, markerEnd), content: line.slice(k) };
