/**
 * `^[ ]{tab,2*tab-1}((\d+\.)|[*+-])[ ]+.*` - an indented (nested) list item.
 */
export function matchIndentedListItem(line, tabLength) {
  let indent = 0;
  while (indent < line.length && line[indent] === ' ') indent += 1;
  if (indent < tabLength || indent > tabLength * 2 - 1) return false;
  return matchListItem(line.slice(indent), tabLength) !== null;
}

/**
 * `^(([ ]{tab})+)` - number of whole indentation units at the front of a block.
 */
export function countIndentUnits(block, tabLength) {
  let units = 0;
  let i = 0;
  while (block.startsWith(' '.repeat(tabLength), i)) {
    units += 1;
    i += tabLength;
  }
  return units;
}

/**
 * `^[ ]{0,3}\[([^\[\]]*)\]:[ ]*\n?[ ]*([^\s]+)[ ]*(?:\n?[ ]*(title)[ ]*)?$`
 * searched line by line (the pattern is `MULTILINE`).
 */
export function searchReference(block) {
  let pos = 0;
  while (pos <= block.length) {
    const found = matchReferenceAt(block, pos);
    if (found !== null) return found;
    const end = lineEnd(block, pos);
    if (end >= block.length) break;
    pos = end + 1;
  }
  return null;
}

function skipSpaces(text, i) {
  while (text[i] === ' ') i += 1;
  return i;
}

/** `[ ]*\n?[ ]*` - optional run of spaces spanning at most one newline. */
function skipSpacesOneNewline(text, i) {
  i = skipSpaces(text, i);
  if (text[i] === '\n') i = skipSpaces(text, i + 1);
  return i;
}

function matchReferenceAt(block, start) {
  const indent = leadingSpaces(block, start, 3);
  let i = start + indent;
  if (block[i] !== '[') return null;
  i += 1;
  const idStart = i;
  while (i < block.length && block[i] !== '[' && block[i] !== ']') i += 1;
  if (block[i] !== ']') return null;
  const id = block.slice(idStart, i);
  i += 1;
  if (block[i] !== ':') return null;
  i += 1;
  i = skipSpacesOneNewline(block, i);
  const linkStart = i;
  while (i < block.length && !isSpace(block[i])) i += 1;
  if (i === linkStart) return null;
  const link = block.slice(linkStart, i);
  const afterLink = i;

  // Optional title; the whole tail must reach the end of a line.
  const tryEnd = (index) => {
    const j = skipSpaces(block, index);
    if (j >= block.length || block[j] === '\n') return j;
    return -1;
  };

  let j = skipSpacesOneNewline(block, afterLink);
  const quote = block[j];
  if (quote === '"' || quote === "'" || quote === '(') {
    const close = quote === '(' ? ')' : quote;
    const bodyStart = j + 1;
    let k = bodyStart;
    while (k < block.length && block[k] !== close) k += 1;
    if (block[k] === close) {
      const nextChar = at(block, k + 1);
      // `(?<!")"[^"]*"(?!")` / `'[^']*'(?!')` - the closing quote must not be
      // doubled up.
      if (!(quote !== '(' && nextChar === quote)) {
        const end = tryEnd(k + 1);
        if (end !== -1) {
          return {
            start: start + indent,
            end,
            id,
            link,
            title: block.slice(bodyStart, k),
          };
        }
      }
    }
  }
  const end = tryEnd(afterLink);
  if (end === -1) return null;
  return { start: start + indent, end, id, link, title: null };
}

