/**
 * Hand written matchers for the block level shapes.
 *
 * Each helper walks the string one character at a time and returns either
 * `null` or a small match record `{start, end, ...}` so the block processors
 * can stay close in shape to the reference implementation.
 */

import { at, isDigit, isSpace, runLength } from '../chars.mjs';

/** Index of the start of the line containing `index`. */
export function lineStart(text, index) {
  const nl = text.lastIndexOf('\n', index - 1);
  return nl === -1 ? 0 : nl + 1;
}

/** Index just past the end of the line containing `index` (excludes `\n`). */
export function lineEnd(text, index) {
  const nl = text.indexOf('\n', index);
  return nl === -1 ? text.length : nl;
}

/** Leading spaces at `index`, capped at `max`. */
function leadingSpaces(text, index, max) {
  let n = 0;
  while (n < max && text[index + n] === ' ') n += 1;
  return n;
}

/**
 * `(?:^|\n)(?P<level>#{1,6})(?P<header>(?:\\.|[^\\])*?)#*(?:\n|$)`
 *
 * Scans for an ATX heading anywhere in the block.  The header body is lazy, so
 * the shortest body that still lets the trailing `#*` reach a line break wins.
 */
export function searchHashHeader(block) {
  for (let pos = 0; pos <= block.length; pos += 1) {
    // `(?:^|\n)` - position 0, or immediately after a newline.
    let start = pos;
    if (pos > 0) {
      if (block[pos - 1] !== '\n') continue;
      start = pos - 1;
    }
    const hashes = runLength(block, pos, '#');
    if (hashes < 1) continue;
    const level = Math.min(hashes, 6);
    const bodyStart = pos + level;
    // Walk the lazy body one character at a time. `(?:\\.|[^\\])` consumes a
    // backslash escape as a unit, so a trailing `\` can never end the body.
    const stops = [];
    let i = bodyStart;
    stops.push(i);
    while (i < block.length) {
      if (block[i] === '\\') {
        if (i + 1 >= block.length) break;
        i += 2;
      } else {
        i += 1;
      }
      stops.push(i);
    }
    for (const bodyEnd of stops) {
      const trailing = runLength(block, bodyEnd, '#');
      // `#*` is greedy but backtracks, so try the longest run first.
      for (let t = trailing; t >= 0; t -= 1) {
        const after = bodyEnd + t;
        if (after >= block.length || block[after] === '\n') {
          return {
            start,
            end: after < block.length ? after + 1 : after,
            level,
            header: block.slice(bodyStart, bodyEnd),
          };
        }
      }
    }
  }
  return null;
}

/**
 * `^.*?\n[=-]+[ ]*(\n|$)` anchored at the start of the block: a setext
 * underline on the second line.
 */
export function matchSetextHeader(block) {
  const nl = block.indexOf('\n');
  if (nl === -1) return null;
  const second = lineEnd(block, nl + 1);
  const rule = block.slice(nl + 1, second);
  if (!rule.length) return null;
  let i = 0;
  while (i < rule.length && (rule[i] === '=' || rule[i] === '-')) i += 1;
  if (i === 0) return null;
  while (i < rule.length && rule[i] === ' ') i += 1;
  if (i !== rule.length) return null;
  return { start: 0, end: second, marker: rule[0] };
