/**
 * `^[ ]{0,3}((-+[ ]{0,2}){3,}|(_+[ ]{0,2}){3,}|(\*+[ ]{0,2}){3,})$` on any
 * line of the block.
 */
export function searchHorizontalRule(block) {
  let pos = 0;
  while (pos <= block.length) {
    const end = lineEnd(block, pos);
    if (matchHorizontalRuleLine(block, pos, end)) return { start: pos, end };
    if (end >= block.length) break;
    pos = end + 1;
  }
  return null;
}

function matchHorizontalRuleLine(block, start, end) {
  const indent = leadingSpaces(block, start, 3);
  let i = start + indent;
  if (i >= end) return false;
  const marker = block[i];
  if (marker !== '-' && marker !== '_' && marker !== '*') return false;
  let groups = 0;
  while (i < end) {
    if (block[i] !== marker) return false;
    while (i < end && block[i] === marker) i += 1;
    let spaces = 0;
    while (i < end && block[i] === ' ' && spaces < 2) { i += 1; spaces += 1; }
    groups += 1;
  }
  return i === end && groups >= 3;
}

/** `(^|\n)[ ]{0,3}>[ ]?(.*)` - the first block quote marker in the block. */
export function searchBlockQuote(block) {
  let pos = 0;
  while (pos <= block.length) {
    const end = lineEnd(block, pos);
    const indent = leadingSpaces(block, pos, 3);
    if (block[pos + indent] === '>') {
      let contentStart = pos + indent + 1;
      if (block[contentStart] === ' ') contentStart += 1;
      return {
        start: pos === 0 ? 0 : pos - 1,
        markerStart: pos,
        content: block.slice(contentStart, end),
