/** Same shape as `searchBlockQuote` but anchored to a single line. */
export function matchBlockQuoteLine(line) {
  const indent = leadingSpaces(line, 0, 3);
  if (line[indent] !== '>') return null;
  let contentStart = indent + 1;
  if (line[contentStart] === ' ') contentStart += 1;
  return line.slice(contentStart);
}

/**
 * `^[ ]{0,3}((\d+\.)|[*+-])[ ]+(.*)` - a list item on a single line.
 * `kind` is `'ol'` or `'ul'`; `marker` is the raw bullet/number text.
 */
export function matchListItem(line, tabLength) {
  const indent = leadingSpaces(line, 0, tabLength - 1);
  let i = indent;
  let kind = null;
  let markerEnd = i;
  if (isDigit(line[i])) {
    let j = i;
    while (j < line.length && isDigit(line[j])) j += 1;
    if (line[j] !== '.') return null;
    kind = 'ol';
    markerEnd = j + 1;
  } else if (line[i] === '*' || line[i] === '+' || line[i] === '-') {
    kind = 'ul';
    markerEnd = i + 1;
  } else {
    return null;
  }
  let k = markerEnd;
  while (k < line.length && line[k] === ' ') k += 1;
  if (k === markerEnd) return null;
  return { kind, marker: line.slice(indent, markerEnd), content: line.slice(k) };
}

/**
 * `^[ ]{tab,2*tab-1}((\d+\.)|[*+-])[ ]+.*` - an indented (nested) list item.
 */
export function matchIndentedListItem(line, tabLength) {
  let indent = 0;
  while (indent < line.length && line[indent] === ' ') indent += 1;
  if (indent < tabLength || indent > tabLength * 2 - 1) return false;
  return matchListItem(line.slice(indent), tabLength) !== null;
}

/**
 * `^(([ ]{tab})+)` - number of whole indentation units at the front of a block.
 */
export function countIndentUnits(block, tabLength) {
  let units = 0;
  let i = 0;
  while (block.startsWith(' '.repeat(tabLength), i)) {
    units += 1;
    i += tabLength;
  }
  return units;
}

/**
 * `^[ ]{0,3}\[([^\[\]]*)\]:[ ]*\n?[ ]*([^\s]+)[ ]*(?:\n?[ ]*(title)[ ]*)?$`
 * searched line by line (the pattern is `MULTILINE`).
 */
export function searchReference(block) {
  let pos = 0;
  while (pos <= block.length) {
    const found = matchReferenceAt(block, pos);
    if (found !== null) return found;
    const end = lineEnd(block, pos);
    if (end >= block.length) break;
    pos = end + 1;
  }
  return null;
}

function skipSpaces(text, i) {
  while (text[i] === ' ') i += 1;
  return i;
}

/** `[ ]*\n?[ ]*` - optional run of spaces spanning at most one newline. */
function skipSpacesOneNewline(text, i) {
  i = skipSpaces(text, i);
  if (text[i] === '\n') i = skipSpaces(text, i + 1);
  return i;
}

function matchReferenceAt(block, start) {
  const indent = leadingSpaces(block, start, 3);
  let i = start + indent;
  if (block[i] !== '[') return null;
  i += 1;
  const idStart = i;
  while (i < block.length && block[i] !== '[' && block[i] !== ']') i += 1;
  if (block[i] !== ']') return null;
