/**
 * Hand written matchers for the inline shapes.
 *
 * Every function scans characters directly.  Lazy quantifiers are modelled by
 * growing a candidate window from the shortest possible length, which is the
 * order a backtracking engine would try them in.
 */

import { at, isAsciiAlnum, isAsciiLetter, isDigit, isHexDigit, isSpace, isWordChar, runLength } from '../chars.mjs';

/**
 * `(?:(?<!\\)((?:\\{2})+)(?=`+)|(?<!\\)(`+)(.+?)(\2))` from `startIndex` on.
 * Returns `{start, end, doubled, code}`: `doubled` is the run of escaped
 * backslashes for the first alternative, `code` the code span body.
 */
export function findBacktick(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length; i += 1) {
    if (data[i] === '\\') {
      // `((?:\\{2})+)(?=`+)` - an even run of backslashes before backticks.
      if (i > 0 && data[i - 1] === '\\') continue;
      const run = runLength(data, i, '\\');
      // Greedy `(?:\\{2})+` then a lookahead for at least one backtick.
      for (let pairs = Math.floor(run / 2); pairs >= 1; pairs -= 1) {
        const end = i + pairs * 2;
        if (data[end] === '`') {
          return { start: i, end, doubled: data.slice(i, end), code: null };
        }
      }
      continue;
    }
    if (data[i] !== '`') continue;
    if (i > 0 && data[i - 1] === '\\') continue;
    const open = runLength(data, i, '`');
    const fence = '`'.repeat(open);
    // `(.+?)` is lazy: the closest matching fence wins.
    for (let bodyEnd = i + open + 1; bodyEnd + open <= data.length; bodyEnd += 1) {
      if (data.startsWith(fence, bodyEnd)) {
        return {
          start: i,
          end: bodyEnd + open,
          doubled: null,
          code: data.slice(i + open, bodyEnd),
        };
      }
    }
  }
  return null;
}

/** `\\(.)` with `DOTALL`. */
export function findEscape(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length - 1; i += 1) {
    if (data[i] === '\\') return { start: i, end: i + 2, char: data[i + 1] };
  }
  return null;
}

/** `(?<!\!)\[` - the opening bracket of a link or reference. */
export function findLinkBracket(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length; i += 1) {
    if (data[i] !== '[') continue;
    if (i > 0 && data[i - 1] === '!') continue;
    return { start: i, end: i + 1 };
  }
  return null;
}

/** `\!\[` - the opening bracket of an image. */
export function findImageBracket(data, startIndex) {
  for (let i = Math.max(0, startIndex); i + 1 < data.length; i += 1) {
    if (data[i] === '!' && data[i + 1] === '[') return { start: i, end: i + 2 };
  }
  return null;
}

/** `<((?:[Ff]|[Hh][Tt])[Tt][Pp][Ss]?://[^<>]*)>` */
export function findAutolink(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length; i += 1) {
    if (data[i] !== '<') continue;
    let j = i + 1;
    const lower = (index) => (data[index] || '').toLowerCase();
    if (lower(j) === 'f') {
      j += 1;
    } else if (lower(j) === 'h' && lower(j + 1) === 't') {
      j += 2;
    } else {
      continue;
    }
    if (lower(j) !== 't') continue;
    j += 1;
    if (lower(j) !== 'p') continue;
    j += 1;
    if (lower(j) === 's') j += 1;
    if (!data.startsWith('://', j)) continue;
    j += 3;
    let k = j;
    while (k < data.length && data[k] !== '<' && data[k] !== '>') k += 1;
    if (data[k] !== '>') continue;
    return { start: i, end: k + 1, url: data.slice(i + 1, k) };
  }
  return null;
}

/** `<([^<> !]+@[^@<> ]+)>` */
export function findAutomail(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length; i += 1) {
    if (data[i] !== '<') continue;
    // `[^<> !]+` is greedy, then `@`, then `[^@<> ]+`, then `>`.
    let localEnd = i + 1;
    while (localEnd < data.length && !'<> !'.includes(data[localEnd])) localEnd += 1;
    for (let atPos = localEnd - 1; atPos > i; atPos -= 1) {
      if (data[atPos] !== '@') continue;
      if (atPos === i + 1) break;
      let k = atPos + 1;
      while (k < data.length && !'@<> '.includes(data[k])) k += 1;
      if (k === atPos + 1) continue;
      if (data[k] !== '>') continue;
      return { start: i, end: k + 1, email: data.slice(i + 1, k) };
    }
  }
  return null;
}

/** `  \n` - a hard line break. */
export function findLineBreak(data, startIndex) {
  const index = data.indexOf('  \n', Math.max(0, startIndex));
  if (index === -1) return null;
  return { start: index, end: index + 3 };
}

/** `(<(\/?[a-zA-Z][^<>]*|!--(?:(?!<!--|-->).)*--)>)` - inline raw HTML. */
export function findInlineHtml(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length; i += 1) {
    if (data[i] !== '<') continue;
    let j = i + 1;
    if (data.startsWith('!--', j)) {
      // `(?:(?!<!--|-->).)*--` then `>`.
      let k = j + 3;
      while (k < data.length) {
        if (data.startsWith('<!--', k)) break;
        if (data.startsWith('-->', k)) {
          return { start: i, end: k + 3, html: data.slice(i, k + 3) };
        }
        k += 1;
      }
      continue;
    }
    if (data[j] === '/') j += 1;
    if (!isAsciiLetter(data[j] || '')) continue;
    j += 1;
    let k = j;
    while (k < data.length && data[k] !== '<' && data[k] !== '>') k += 1;
    if (data[k] !== '>') continue;
    return { start: i, end: k + 1, html: data.slice(i, k + 1) };
  }
  return null;
}

/** `(&(?:\#[0-9]+|\#x[0-9a-fA-F]+|[a-zA-Z0-9]+);)` */
export function findEntity(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length; i += 1) {
    if (data[i] !== '&') continue;
    let j = i + 1;
    if (data[j] === '#') {
      j += 1;
      if (data[j] === 'x') {
        j += 1;
        const from = j;
        while (j < data.length && isHexDigit(data[j])) j += 1;
        if (j === from) continue;
      } else {
        const from = j;
        while (j < data.length && isDigit(data[j])) j += 1;
        if (j === from) continue;
      }
    } else {
      const from = j;
      while (j < data.length && isAsciiAlnum(data[j])) j += 1;
      if (j === from) continue;
    }
    if (data[j] !== ';') continue;
    return { start: i, end: j + 1, html: data.slice(i, j + 1) };
  }
  return null;
}

/** `((^|\s)(\*{1,3}|_{1,3})(\s|$))` - a stand-alone emphasis character. */
export function findNotStrong(data, startIndex) {
  for (let i = Math.max(0, startIndex); i < data.length; i += 1) {
    let markerStart = i;
    if (i === 0) {
      // `^` matched; the marker begins right here.
    } else if (isSpace(data[i])) {
      markerStart = i + 1;
    } else {
      continue;
    }
    const ch = data[markerStart];
    if (ch !== '*' && ch !== '_') continue;
    const run = runLength(data, markerStart, ch);
    // `\*{1,3}` is greedy but backtracks down to a single character.
    for (let n = Math.min(run, 3); n >= 1; n -= 1) {
      const after = markerStart + n;
      if (after >= data.length || isSpace(data[after])) {
        const end = after >= data.length ? after : after + 1;
        return { start: i, end, text: data.slice(i, end) };
      }
    }
  }
  return null;
}

/** Every index of `ch` at or after `startIndex` (the `\*` / `_` triggers). */
export function findChar(data, startIndex, ch) {
  const index = data.indexOf(ch, Math.max(0, startIndex));
  if (index === -1) return null;
  return { start: index, end: index + 1 };
}

/* ------------------------------------------------------------------ *
 * Emphasis / strong shapes, all anchored at an explicit position.
 * ------------------------------------------------------------------ */

const notWordBefore = (data, pos) => pos === 0 || !isWordChar(data[pos - 1]);
const notWordAfter = (data, pos) => pos >= data.length || !isWordChar(data[pos]);

/** `(C)\1{2}(.+?)\1(.*?)\1{2}` - `***em strong***`. */
export function matchEmStrong(data, pos, ch) {
  const triple = ch.repeat(3);
  if (!data.startsWith(triple, pos)) return null;
  const bodyStart = pos + 3;
  for (let i = bodyStart + 1; i < data.length; i += 1) {
    if (data[i] !== ch) continue;
    for (let j = i + 1; j <= data.length; j += 1) {
      if (data.startsWith(ch.repeat(2), j)) {
        return {
          start: pos,
          end: j + 2,
          groups: [data.slice(bodyStart, i), data.slice(i + 1, j)],
        };
      }
    }
  }
  return null;
}

/** `(C)\1{2}(.+?)\1{2}(.*?)\1` - `***strong**em*`. */
export function matchStrongEm(data, pos, ch) {
  const triple = ch.repeat(3);
  const double = ch.repeat(2);
  if (!data.startsWith(triple, pos)) return null;
  const bodyStart = pos + 3;
