  for (let i = bodyStart + 1; i < data.length; i += 1) {
    if (data[i] !== ch) continue;
    for (let j = i + 1; j <= data.length; j += 1) {
      if (data.startsWith(ch.repeat(2), j)) {
        return {
          start: pos,
          end: j + 2,
          groups: [data.slice(bodyStart, i), data.slice(i + 1, j)],
        };
      }
    }
  }
  return null;
}

/** `(C)\1{2}(.+?)\1{2}(.*?)\1` - `***strong**em*`. */
export function matchStrongEm(data, pos, ch) {
  const triple = ch.repeat(3);
