    if (!data.startsWith(double, i)) continue;
    for (let j = i + 2; j < data.length; j += 1) {
      if (data[j] === ch) {
        return {
          start: pos,
          end: j + 1,
          groups: [data.slice(bodyStart, i), data.slice(i + 2, j)],
        };
      }
    }
