    if (data[i] !== '*') continue;
    if (data[i + 1] === '*') continue;
    for (let j = i + 2; j < data.length; j += 1) {
      if (data.startsWith('***', j)) {
        return {
          start: pos,
          end: j + 3,
          groups: [data.slice(bodyStart, i), data.slice(i + 1, j)],
        };
      }
    }
  }
