  for (let i = bodyStart + 1; i < data.length; i += 1) {
    if (data[i] !== '_') continue;
    if (isWordChar(data[i - 1])) continue;
    if (data[i + 1] === '_') continue;
    for (let j = i + 2; j < data.length; j += 1) {
      if (!data.startsWith('___', j)) continue;
      if (!notWordAfter(data, j + 3)) continue;
      return {
        start: pos,
        end: j + 3,
        groups: [data.slice(bodyStart, i), data.slice(i + 1, j)],
